+  // weight prefetch before the PDL wait (input-independent addresses)
+  uint4 w_vec[kChunksPerWarp];
+#pragma unroll
+  for (uint32_t c = 0; c < kChunksPerWarp; ++c) {
+    w_vec[c] = *reinterpret_cast<const uint4*>(w_row + (warp * kChunksPerWarp + c) * 32 + 8 * t);
